entries[73680] = { ["name"] = "Elemente entfesseln", ["text"] = "8.2% von Grundmana 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\nFokussiert die Elementarkraft, die in der Bewaffnung des Schamanen gebündelt ist und setzt sie frei. Der konzentrierte Effekt entspricht der entfesselten Verzauberung. [ Beidhändigkeit : Wenn beide Waffen mit der gleichen Verzauberung versehen sind, wird nur eine entfesselt werden ]\nDie Einzelheiten der Entfesslungseffekte sind in den Tooltips der jeweiligen Waffenverzauberungen erfasst." }
entries[73681] = { ["name"] = "Wind entfesseln", ["text"] = "100 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nEntfesselt die auf der Waffe des Schamanen liegende Windzornverzauberung, wodurch einem feindlichen Ziel 90% Waffenschaden zugefügt werden. Zudem wird das Nahkampfangriffstempo des Schamanen um 50% erhöht. Hält 6 Waffenschwünge oder 12 Sek. lang an." }
entries[73682] = { ["name"] = "Frost entfesseln", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt die auf der Waffe des Schamanen liegende Frostbrandverzauberung, wodurch einem feindlichen Ziel 969 Frostschaden zugefügt werden und sein Bewegungstempo 5 Sek. lang um 50% verringert wird. Der Effekt wird verstärkt, wenn das Ziel bereits von einem bewegungsverringernden Frosteffekt betroffen ist." }
entries[73683] = { ["name"] = "Flammen entfesseln", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt die auf der Waffe des Schamanen liegende Flammenzungenverzauberung, wodurch einem gegnerischen Ziel 1241 Feuerschaden zugefügt wird und der verursachte Schaden des nächsten Feuerzaubers des Schamanen um 30% erhöht wird." }
entries[73684] = { ["name"] = "Erde entfesseln", ["text"] = "100 Meter Reichweite\nSofort 15 sek. Abklingzeit\nEntfesselt die auf der Waffe des Schamanen liegende Felsbeißerverzauberung, befiehlt dem Ziel, Euch anzugreifen, und erhöht die von Euch gegen das Ziel erzeugte Bedrohung für 5 Sek. um 200%." }
entries[73685] = { ["name"] = "Leben entfesseln", ["text"] = "100 Meter Reichweite\nSofort 15 sek. Abklingzeit\nEntfesselt die auf der Waffe des Schamanen liegende Lebensgeisterverzauberung, wodurch ein befreundetes Ziel um 3154 geheilt und der Effekt der nächsten direkten Heilung oder von 'Heilender Regen' des Schamanen um 30% erhöht wird." }
entries[73686] = { ["name"] = "Fixieren", ["text"] = "100 Meter Reichweite\nSofort\nSorgt dafür, dass ein Gegner bis Abbruch lang fixiert ist." }
entries[73687] = { ["name"] = "Fixieren", ["text"] = "40 Meter Reichweite\nSofort\nDas Ziel ist auf den Zaubernden fixiert." }
