entries[74001] = { ["name"] = "Kampfbereitschaft", ["text"] = "Sofort 2 min Abklingzeit\nGeht in einen Zustand erhöhter Wahrnehmung über, in dem Ihr feindliche Waffenstöße mit zunehmender Effektivität abwehrt. Aufeinanderfolgende Angriffe verursachen pro Anwendung 10% weniger Schaden, dieser Effekt ist bis zu 5-mal stapelbar.\n\nHält 20 Sek. lang an. Vergehen jedoch 10 Sek., ohne dass ein Angriff geschieht, endet dieser Zustand.\n(1s Abklingzeit)" }
